item.command:
/bin/bash -lc "python3 - <<'PY'
import json,collections,datetime
for fn in ['revisions','events','pages','labels']:
 p='data/'+fn+'.jsonl'; rows=[json.loads(x) for x in open(p)]
 print('\\n',fn,len(rows))
 for k in ['time','write_date','first_write','last_write']:
  vals=[r.get(k) for r in rows if r.get(k)]
  if vals: print(k,min(vals),max(vals))
 if fn=='revisions':
  print('wikis',collections.Counter(r['page_id'].split('/')[0] for r in rows))
  print('actions',collections.Counter(r.get('request_action') for r in rows).most_common(15))
  print('summaries',collections.Counter(r.get('change_summary') for r in rows).most_common(10))
 if fn=='events':
  print('event types',collections.Counter(r.get('event_type') for r in rows))
  print('actions',collections.Counter(r.get('request_action') for r in rows).most_common(20))
PY"

