item.command:
/bin/bash -lc "sed -n '1,240p' prompt.txt && python3 - <<'PY'
import json,collections
E=[json.loads(x) for x in open('data/events.jsonl')]
for typ in ['revert','probe']:
 print('\\n',typ)
 for e in E:
  if e['event_type']==typ: print(e)
print('\\nfirst/last deletes per wiki and actor/ip')
D=[e for e in E if e['event_type']=='delete']
for wiki in sorted(set(e['wiki'] for e in D)):
 x=[e for e in D if e['wiki']==wiki]
 print(wiki,len(x),x[0],x[-1])
PY"

